#!/usr/bin/env node
// Regenerates Sources/SwiftRightBridge/RepairGuardScript.swift from guard/repair-guard.ps1 (the one source of the script).
//   node tools/gen-repair-guard.mjs          write
//   node tools/gen-repair-guard.mjs --check  exit 1 when the generated file is stale
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const src = readFileSync(path.join(root, "guard", "repair-guard.ps1"), "utf8").replace(/\r\n/g, "\n");
if (src.includes('"""#')) throw new Error("script contains the raw-string terminator");
const out = `// GENERATED by tools/gen-repair-guard.mjs from guard/repair-guard.ps1. Do not edit.
enum RepairGuardScript {
    static let source = #"""
${src.replace(/\n$/, "")}
"""#
}
`;
const target = path.join(root, "Sources", "SwiftRightBridge", "RepairGuardScript.swift");
if (process.argv.includes("--check")) {
  let cur = ""; try { cur = readFileSync(target, "utf8"); } catch {}
  if (cur !== out) { console.error("RepairGuardScript.swift is stale; run node tools/gen-repair-guard.mjs"); process.exit(1); }
} else { writeFileSync(target, out); console.log("wrote " + target); }
